INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-02' FROM countries WHERE name_en = 'Egypt';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Centralized clearance — ETA platform (e-invoices + e-receipts)', 'This deep-dive page reflects publicly available technical guidance as of August 2026 and is provided for general awareness, not legal or tax advice. The ETA adjusts wave scopes, thresholds, and penalty practice by decision and circular — confirm current requirements directly with the Egyptian Tax Authority or your integration provider before building against them.', 'Egypt''s rollout ran as two parallel tracks under one authority: ETA-cleared B2B/B2G e-invoicing phased in from November 2020 and universal by April 2023, and a separate B2C e-receipt system rolled out in staged waves — with 2026 marking the shift from onboarding to enforcement.', 'Egypt uses its own ETA-defined structured formats rather than an EU-style standard: JSON or XML documents, digitally signed, carrying standardized product codes, and cleared by the central platform which assigns each document its official UUID.', 'Everything routes through the ETA''s central platform: invoices are cleared in real or near-real time via API integration, the web portal, or the mobile app, while consumer receipts flow from POS systems integrated with the parallel e-receipt system.', 'Getting compliant means registering with the ETA, obtaining a digital certificate, mapping your product codes, and integrating each sales channel — with the invoice and receipt tracks needing separate attention.', 'Egypt backs the mandate with real teeth: explicit fines for late submission and missed registration since 2026, denial of VAT input credits on non-cleared documents, and consequence-based enforcement reaching import/export rights and government contracts.', 'Egypt''s ETA-cleared e-invoicing has been mandatory for all VAT-registered businesses since April 2023, with paper invoices losing VAT-deduction validity from July 2023 and a parallel B2C e-receipt rollout. Since January 2026 the regime is in its enforcement stage: late-submission penalties, QR codes on printed receipts, and a registration threshold cut to EGP 250,000.', '🏛️' FROM countries WHERE name_en = 'Egypt';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Egypt';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Clearance', 'Centralized ETA model');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Egypt';
