INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'ETA e-invoicing portal');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.eta.gov.eg', 1 FROM countries WHERE name_en = 'Egypt';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Egyptian Tax Authority');
